#!/usr/bin/env node
/* Generates the /image/compress/to-<n>kb/ landing pages.
 *   node tools/make-size-pages.js
 *
 * These target a query family the head term cannot reach: nobody outranks
 * iLoveIMG for "image compressor", but "compress image to 100kb" is won by
 * small sites every day. Each page is a real, working, single-purpose tool —
 * not a doorway — and each carries copy specific to why someone wants that
 * exact ceiling.
 *
 * One template, one data table. Editing a generated file by hand is pointless:
 * the next run overwrites it. Edit this and re-run.
 */
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.join(__dirname, '..');

const TARGETS = [
  {
    kb: 20,
    why: 'Government and exam portals are the usual reason for a 20 KB ceiling — ' +
      'many Indian application forms cap the photo or signature upload at exactly this size.',
    q: 'Will a photo still be legible at 20 KB?',
    a: 'For a passport-style headshot, yes. 20 KB is tight for a full-scene photograph, ' +
      'so if quality alone cannot get there the image is scaled down and you are told by how much.'
  },
  {
    kb: 50,
    why: 'A 50 KB ceiling is common for forum avatars, email signatures and older ' +
      'upload forms that were written when bandwidth was expensive.',
    q: 'Which format do I get back?',
    a: 'JPEG. It is the only widely-accepted format that hits a small hard ceiling ' +
      'predictably — PNG is lossless, so it cannot be dialled down to an arbitrary size.'
  },
  {
    kb: 100,
    why: '100 KB is the usual advice for images on a web page: small enough not to ' +
      'hurt your Largest Contentful Paint, large enough to still look right on a retina screen.',
    q: 'Is 100 KB actually the right size for a web image?',
    a: 'It is a good default for a content image. Hero images can justify more; ' +
      'thumbnails and icons should be far less. If page speed is the goal, WebP at the ' +
      'same visual quality is usually smaller again.'
  },
  {
    kb: 500,
    why: 'Instagram, WhatsApp and most email attachments are comfortable around ' +
      '500 KB — small enough to send instantly, big enough to keep detail in a full photo.',
    q: 'Should I compress before uploading to Instagram?',
    a: 'Yes. Instagram re-compresses whatever you give it, and it is gentler on an ' +
      'image that is already close to its target than on a 12 MB original.'
  }
];

const page = (t) => `<!DOCTYPE html>
<!-- GENERATED by tools/make-size-pages.js — edit that file, not this one. -->
<html lang="en">
<head>
  <meta charset="UTF-8"/>
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>Compress Image to ${t.kb}KB — Free, Exact Size, No Upload</title>
  <meta name="description" content="Compress a JPG or PNG down to ${t.kb} KB or under, free and in your browser. Pick the file, get it back at the size you need. Nothing is uploaded."/>
  <meta name="robots" content="index, follow, max-image-preview:large"/>
  <link rel="canonical" href="./"/>
  <meta property="og:type" content="website"/>
  <meta property="og:title" content="Compress Image to ${t.kb}KB — Free, Exact Size, No Upload"/>
  <meta property="og:description" content="Drop an image and get it back at ${t.kb} KB or under. Runs entirely in your browser — nothing is uploaded."/>
  <meta property="og:image" content="../../../assets/og.png"/>
  <meta name="twitter:card" content="summary_large_image"/>
  <meta name="theme-color" content="#09090b" media="(prefers-color-scheme: dark)"/>
  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)"/>
  <link rel="icon" href="../../../assets/favicon.svg" type="image/svg+xml"/>
  <link rel="apple-touch-icon" href="../../../assets/apple-touch-icon.png"/>
  <link rel="manifest" href="../../../manifest.json"/>
  <link rel="stylesheet" href="../../../css/style.css"/>
  <script src="../../../js/theme.js"></script>
</head>
<body>
<a class="skip-link" href="#main">Skip to content</a>
<nav>
  <div class="nav-inner">
    <a href="../../../index.html" class="logo" aria-label="Nought home">
      <span class="logo-icon"><img src="../../../assets/logo-icon.svg" alt="" width="18" height="18"/></span>
      Nought
    </a>
    <div class="nav-links">
      <a href="../../../index.html#image" class="active">Image</a>
      <a href="../../../index.html#pdf">PDF</a>
      <a href="../../../index.html#text">Text</a>
      <a href="../../../index.html#calculators">Calculators</a>
      <a href="../../../index.html#developer">Developer</a>
    </div>
  </div>
</nav>

<div class="page-wrapper container" id="main">
  <header class="tool-page-header">
    <nav class="breadcrumb" aria-label="Breadcrumb">
      <a href="../../../index.html">Home</a> <span class="breadcrumb-sep">/</span>
      <a href="../index.html">Image Compressor</a> <span class="breadcrumb-sep">/</span>
      <span aria-current="page">To ${t.kb} KB</span>
    </nav>
    <h1 class="tool-page-title">Compress an image to ${t.kb} KB</h1>
    <p class="tool-page-desc">Drop in a JPG or PNG and get it back at ${t.kb} KB or under.
      It searches for the highest quality that still fits, so you get the best-looking
      file that meets the limit rather than the smallest one.</p>
    <div class="tool-badges">
      <span class="badge">Runs on your device</span>
      <span class="badge">Nothing uploaded</span>
      <span class="badge">Exact ceiling</span>
    </div>
  </header>

  <div class="tool-panel" id="sizeTool" data-target-kb="${t.kb}">
    <div class="drop-zone" id="dropZone" aria-label="Choose an image to compress to ${t.kb} KB">
      <svg class="drop-zone-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="M17 8l-5-5-5 5"/><path d="M12 3v12"/></svg>
      <p class="drop-zone-text">Drop an image here, or click to choose</p>
      <p class="drop-zone-sub">JPG, PNG or WebP · pasting from the clipboard works too</p>
      <input type="file" id="fileInput" accept="image/*"/>
    </div>

    <div id="result" hidden>
      <div class="preview-frame" style="margin-top:14px">
        <img id="resultImg" alt="Compressed result" hidden/>
      </div>
      <p class="live-status ok" id="resultStats" style="margin-top:10px"></p>
      <p class="input-hint" id="resultNote" hidden></p>
      <div class="btn-group" style="margin-top:12px">
        <button class="btn btn-primary" id="saveBtn" disabled>Download</button>
        <a class="btn btn-secondary" href="../index.html">Need finer control?</a>
      </div>
    </div>
  </div>

  <section class="faq-section">
    <h2>About the ${t.kb} KB limit</h2>
    <p style="font-size:0.88rem;color:var(--text-secondary);line-height:1.65;margin-bottom:14px">${t.why}</p>
    <div class="faq-item">
      <button class="faq-q">How does it hit the size exactly?
        <svg class="faq-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button>
      <div class="faq-a"><div>It binary-searches the JPEG quality setting, keeping the largest file that still
        fits under ${t.kb} KB — the biggest file under the ceiling is the best-looking one. If even low
        quality is too big, it scales the image down in steps and searches again, and tells you what it did.</div></div>
    </div>
    <div class="faq-item">
      <button class="faq-q">${t.q}
        <svg class="faq-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button>
      <div class="faq-a"><div>${t.a}</div></div>
    </div>
    <div class="faq-item">
      <button class="faq-q">Is my image uploaded anywhere?
        <svg class="faq-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button>
      <div class="faq-a"><div>No. The compression happens in this tab using Canvas. Your image never touches
        a server, which is also why it keeps working with no network once the page has loaded.</div></div>
    </div>
  </section>

  <nav class="related" aria-label="Other size targets">
    <h2>Other sizes</h2>
    <div class="related-grid">
      ${TARGETS.filter((o) => o.kb !== t.kb)
        .map((o) => `<a class="related-card" href="../to-${o.kb}kb/index.html">Compress to ${o.kb} KB</a>`)
        .join('\n      ')}
      <a class="related-card" href="../index.html">Full image compressor</a>
    </div>
  </nav>
</div>

<footer data-auto></footer>

<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "SoftwareApplication",
  "name": "Compress Image to ${t.kb}KB",
  "applicationCategory": "MultimediaApplication",
  "operatingSystem": "Any browser",
  "offers": {"@type": "Offer", "price": "0", "priceCurrency": "USD"}
}
</script>

<script src="../../../js/tools-core.js"></script>
<script src="../../../js/main.js"></script>
<script src="../../../js/target-compress.js"></script>
</body>
</html>
`;

let written = 0;
for (const t of TARGETS) {
  const dir = path.join(ROOT, 'image', 'compress', `to-${t.kb}kb`);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, 'index.html'), page(t));
  console.log(`  image/compress/to-${t.kb}kb/`);
  written++;
}
console.log(`${written} size-target pages generated.`);

// The list the sitemap and the service worker have to agree with.
module.exports = { TARGETS, paths: TARGETS.map((t) => `image/compress/to-${t.kb}kb`) };
